{
  "understanding": {
    "purpose": "Show league positions after 28 matches, supporting comparison of teams’ records, goal differences and points.",
    "reading": "Readers scan down the team names to find a club, then across its row to read its record; they also compare individual statistics down columns. Points and goal difference are especially relevant to standings.",
    "groups": [
      "P, W, D and L describe matches played and results.",
      "GF, GA and GD describe goals scored, conceded and the resulting difference.",
      "Team identifies each row; Pts summarizes the points earned."
    ],
    "keep_intact": [
      "Numeric values, including the sign on goal differences.",
      "Column headers and individual words in team names, where width permits."
    ],
    "may_wrap": [
      "Team names can wrap at spaces; their longer rows can absorb the extra line while the statistics remain aligned with the team."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [108, 40, 38, 32, 38, 41, 43, 49, 45],
      "idea": "At 414px, preserve every word, header and number while allowing team names to wrap naturally; readers scroll to reach the rightmost statistics."
    },
    {
      "name": "B",
      "widths": [90, 35, 34, 30, 34, 35, 36, 34, 31],
      "idea": "Fit the full table into 359px without horizontal scrolling, accepting broken team words and split numeric values in exchange for seeing all columns at once."
    },
    {
      "name": "C",
      "widths": [189, 40, 38, 32, 38, 41, 43, 49, 45],
      "idea": "At 495px, keep team names and statistics on one line for easy row scanning, accepting more horizontal scrolling to reach goal difference and points."
    }
  ]
}
